import{_ as i,l as n,o as e,c as s,v as l,p as o,x as r,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"机群公平调度","description":"","frontmatter":{"title":"机群公平调度","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cluster-fair-scheduling.md","filePath":"llm/cluster-fair-scheduling.md","lastUpdated":1789023840000}'),A={name:"llm/cluster-fair-scheduling.md"};function h(c,a,u,m,B,g){const t=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="机群公平调度" tabindex="-1">机群公平调度 <a class="header-anchor" href="#机群公平调度" aria-label="Permalink to &quot;机群公平调度&quot;">​</a></h1><div class="epigraph"><p>训练作业要一整组同时到齐才开始，推理作业要低延迟插队。公平若按单卡秒计算，会系统性地饿死 gang，或让交互队列永远排在千卡作业后面。</p><footer>—— 对照 Dominant Resource Fairness 与 Kubernetes / Slurm 上的 gang scheduling 实践</footer></div><p><a href="/llm/gpu-failure-modes">上一课</a> 让作业会重启、会占着坏槽位。本课写多作业如何分集群。缺口是 LLM 训练的 <strong>gang 约束</strong>（TP / <a href="/llm/nvlink">NVLink</a> 域必须同时分配）与公平指标（CPU、GPU、功率、轨）不是一维的。集合通信课序在此收束集群运行；下一单元才离开 NVIDIA 主线看其他加速器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典公平：每用户一份 GPU 时间。训练作业要 \\(N\\) 卡同时、且最好在同一轨 / 同一超节点，否则 <a href="/llm/collective-bandwidth-model">带宽模型</a> 作废。若调度器先填满碎片空位，大作业永远凑不齐，小作业享受「公平」，集群 FLOPS 碎片化。反过来，若永远让最大作业占满超节点，研究队列与在线推理被饿死。</p><p>DRF（Ghodsi 等）在多维资源上按主导份额切蛋糕，仍不够：还要拓扑（同轨、同域）、时间（抢占检查点）、以及功率预算。问题是调度目标函数必须包含 <strong>拓扑可行的 gang</strong>，而不是先分配再抱怨 NCCL 慢。</p><p><span class="marginnote">Kubernetes 默认不理解 NVLink 域。需要设备插件、拓扑标签、与 gang 插件（或 Volcano / 专用训练调度）。Slurm 有拓扑与 gang 传统，但要把 GPU 轨写成节点特征。名字不重要，约束要在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>资源模型至少包括：GPU 型号、NVLink 域 id、rail id、功率余量、是否液冷维护窗。训练作业提交时声明并行网格，调度器要么整组放进兼容域，要么拒绝，而不是拆开。推理 / 交互队列用预留或抢占：抢占必须落在检查点边界，否则公平的代价是几天的 step。</p><p>配额按团队的主导资源（通常是 GPU·小时，但高密度柜要用 kW·小时校正，避免有人占满电）。故障重启计入该团队配额，否则坏作业靠重试侵占集群——这是故障课与公平的交接。</p>',10)),(e(),o(p,null,{default:r(()=>[E(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20JOB%5B%22%E4%BD%9C%E4%B8%9A%3A%20%E7%BD%91%E6%A0%BC%20%2B%20%E6%8B%93%E6%89%91%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20FIT%5B%22%E5%8C%B9%E9%85%8D%E5%9F%9F%20%2F%20%E8%BD%A8%20%2F%20%E5%8A%9F%E7%8E%87%22%5D%0A%20%20FIT%20--%3E%20GANG%5B%22%E5%90%8C%E6%97%B6%E5%90%AF%E5%8A%A8%E6%95%B4%E7%BB%84%22%5D%0A%20%20FIT%20--%3E%20WAIT%5B%22%E7%AD%89%E5%BE%85%E6%95%B4%E6%AE%B5%E7%A9%BA%E9%97%B2%22%5D%0A%20%20PRE%5B%22%E4%BA%A4%E4%BA%92%E9%A2%84%E7%95%99%22%5D%20--%3E%20GPU%5B%22%E9%83%A8%E5%88%86%E5%8D%A1%22%5D%0A%20%20GANG%20--%3E%20RUN%5B%22%E8%AE%AD%E7%BB%83%22%5D%0A%20%20RUN%20--%3E%20CK%5B%22%E5%8F%AF%E6%8A%A2%E5%8D%A0%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>多租户轨隔离：尽量不要让两个大 DP 作业共享同一轨的剩余带宽，除非有 QoS。共享会让双方的 \\(\\beta\\) 模型同时失效，表现为「公平的慢」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Gang 启动的尾延迟来自最慢那张卡的准备（加载权重、数据预热）。弹性缩放中途改 \\(N\\) 要换进程组，集体拓扑重建，\\(\\alpha\\) 会抖一段时间。公平策略若频繁抢占大作业，集群会把时间花在检查点与重启上，有效公平为负。</p><p>DRF 的主导份额在「GPU 很满、功率已尽」时会把功率当主导维，拒绝再塞训练作业——这是正确的，尽管 GPU 计数还显示空闲。调度 UI 必须暴露这一维，否则用户以为系统空转。</p><p><span class="marginnote">抢占推理来填满训练间隙，会伤害尾延迟 SLA。反过来用推理填训练碎片，要保证碎片落在域外或独立副本，不要插入 TP 组。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在以太网碎片上拼 64 路 TP 还称为「已调度」。不要把公平写成纯等待时间而不计拓扑质量。不要让无限重试的崩溃作业绕过配额。集合通信与集群运行到此结束；下一课从 TPU 开始，对照「不是 NCCL + NVLink」的加速器如何做集体与调度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>训练是拓扑约束下的 gang；按单卡填充会碎片化或饿死大作业。</li><li>公平是多维的：GPU、功率、轨、域，可用 DRF 思想加拓扑匹配。</li><li>抢占必须落在检查点；故障重试计入配额。</li><li>空闲 GPU 计数在功率或冷却见顶时是假象。</li><li>出处：Ghodsi 等 DRF；K8s / Slurm 上的 gang 与拓扑调度实践。</li></ul>',9))])}const D=i(A,[["render",h]]);export{P as __pageData,D as default};
